const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const taiwan = ee.Geometry.Rectangle([119.0, 21.5, 122.5, 25.5]);
  const startDate1 = '2020-02-10';
  const endDate1 = '2020-02-25';
  const startDate2 = '2020-04-20';
  const endDate2 = '2020-05-12';
  const band = 'tropospheric_NO2_column_number_density';

  // 2. Data Acquisition
  const collection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
    .select([band, 'qa_value'])
    .filterBounds(taiwan);

  const col1 = collection.filterDate(startDate1, endDate1);
  const col2 = collection.filterDate(startDate2, endDate2);

  // Check for empty collections
  const size1 = col1.size().getInfo();
  const size2 = col2.size().getInfo();

  if (size1 === 0 || size2 === 0) {
    console.log(`Image count Period 1 (Feb): ${size1}`);
    console.log(`Image count Period 2 (Apr-May): ${size2}`);
    console.log("Empty collection for one or both periods.");
    console.log("C1");
    return;
  }
  console.log(`Image count Period 1 (Feb): ${size1}`);
  console.log(`Image count Period 2 (Apr-May): ${size2}`);

  // 3. Processing: Mask low quality pixels and create mean composites
  const maskAndSelect = function(image) {
    const qaMask = image.select('qa_value').gt(0.75);
    return image.select(band).updateMask(qaMask);
  };

  const image1 = col1.map(maskAndSelect).mean();
  const image2 = col2.map(maskAndSelect).mean();

  // 4. Calculation
  const scale = 3000; // Use a coarser scale to avoid timeout

  const stats1 = image1.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: taiwan,
    scale: scale,
    maxPixels: 1e9
  });

  const stats2 = image2.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: taiwan,
    scale: scale,
    maxPixels: 1e9
  });

  const mean1 = stats1.get(band).getInfo();
  const count1 = stats1.get(band + '_count').getInfo();
  const mean2 = stats2.get(band).getInfo();
  const count2 = stats2.get(band + '_count').getInfo();

  // 5. Validation & Final Answer
  if (count1 === 0 || count2 === 0) {
    console.log(`Valid pixel count Period 1: ${count1}`);
    console.log(`Valid pixel count Period 2: ${count2}`);
    console.log("No valid pixels after cloud/quality masking.");
    console.log("C2");
    return;
  }
   console.log(`Valid pixel count Period 1: ${count1}`);
   console.log(`Valid pixel count Period 2: ${count2}`);

  if (mean1 === null || mean2 === null) {
    console.log("Calculation resulted in null.");
    console.log("C3");
    return;
  }

  // Sentinel-5P NO2 is in mol/m^2. Multiply by 1e6 for a more readable umol/m^2.
  const conversionFactor = 1e6;
  const mean1_converted = mean1 * conversionFactor;
  const mean2_converted = mean2 * conversionFactor;

  console.log(`Feb 2020 Mean NO2 (umol/m^2): ${mean1_converted.toFixed(2)}`);
  console.log(`Apr-May 2020 Mean NO2 (umol/m^2): ${mean2_converted.toFixed(2)}`);

  if (mean2_converted > mean1_converted) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
    console.error(err);
    console.log("D");
});
